import {cms} from '@/cms'
import {Query} from 'alinea'

// Several ids
await cms.find({id: {in: ['2g8FtR', '2g8FtS']}})

// Everything below /docs
await cms.find({url: {startsWith: '/docs/'}})

// Top-level entries of a root, for a main menu
await cms.find({
  root: cms.workspaces.main.pages,
  level: 0,
  select: {title: Query.title, url: Query.url}
})

// Entries below a seeded page
await cms.find({location: cms.workspaces.main.pages.blog})

import {cms} from '@/cms'
import {Query} from 'alinea'

export async function pageByUrl(locale: string, slug: Array<string>) {
  return cms.first({
    locale,
    url: `/${[locale, ...slug].join('/')}`,
    select: {title: Query.title, type: Query.type}
  })
}

import {cms} from '@/cms'
import {BlogPost} from '@/schema'
import {Query} from 'alinea'

// All fields of the post, plus its parent
const post = await cms.get({
  type: BlogPost,
  path: 'hello-world',
  include: {
    blog: Query.parent({select: {title: Query.title, url: Query.url}})
  }
})

// Only what the card needs
const card = await cms.get({
  type: BlogPost,
  path: 'hello-world',
  select: {
    title: Query.title,
    intro: BlogPost.intro,
    blog: Query.parent({select: {title: Query.title, url: Query.url}})
  }
})

import {cms} from '@/cms'
import {BlogPost} from '@/schema'
import {Query} from 'alinea'

const page = 2
const perPage = 10

const posts = await cms.find({
  type: BlogPost,
  select: {title: Query.title, url: Query.url},
  orderBy: [
    // Newest first
    {desc: BlogPost.publishDate},
    // Same date: alphabetical
    {asc: Query.title}
  ],
  skip: (page - 1) * perPage,
  take: perPage
})

import {cms} from '@/cms'
import {BlogPost} from '@/schema'
import {Query} from 'alinea'

// The first post of every blog
const firstPosts = await cms.find({
  type: BlogPost,
  groupBy: Query.parentId,
  select: {title: Query.title, url: Query.url}
})
